package com.enerlution.ems.business;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import com.enerlution.ems.auth.AccessControl;import com.enerlution.ems.common.BusinessException;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.*;import org.springframework.transaction.support.*;
@EnabledIfEnvironmentVariable(named="EMS_TOYINGZHEN_TESTS",matches="true") class StationDisplaySettingsPostgresTest{
 JdbcTemplate db;AccessControl access;StationDisplaySettingsController c;DataSourceTransactionManager manager;TransactionStatus tx;
 @BeforeEach void setup()throws Exception{var ds=new DriverManagerDataSource(System.getenv("EMS_TOYINGZHEN_DB_URL"),System.getenv("EMS_TOYINGZHEN_DB_USER"),System.getenv("EMS_TOYINGZHEN_DB_PASSWORD"));manager=new DataSourceTransactionManager(ds);tx=manager.getTransaction(new DefaultTransactionDefinition());db=new JdbcTemplate(ds);assertEquals("ems_cloud_saas_toyingzhen",db.queryForObject("SELECT current_database()",String.class));db.execute("CREATE SCHEMA display_test_"+UUID.randomUUID().toString().replace("-",""));String schema=db.queryForObject("SELECT nspname FROM pg_namespace WHERE nspname like 'display_test_%' ORDER BY oid DESC LIMIT 1",String.class);db.execute("SET LOCAL search_path TO "+schema);db.execute("CREATE TABLE station(id bigint PRIMARY KEY,tenant_id bigint);CREATE TABLE app_user(id bigint PRIMARY KEY,display_name text);CREATE TABLE audit_event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id bigint,target_tenant_id bigint,action text,detail text);CREATE TABLE station_audit_event(event_id bigint,station_id bigint,shared_detail boolean,channel text,actor_name text);INSERT INTO station VALUES(101,11),(102,22);INSERT INTO app_user VALUES(7,'Test')");db.execute(Files.readString(Path.of("src/main/resources/db/migration/V49__station_display_settings.sql")));access=mock(AccessControl.class);when(access.userId()).thenReturn(7L);c=new StationDisplaySettingsController(new DomainSupport(db,access));}
 @AfterEach void cleanup(){if(tx!=null)manager.rollback(tx);}
 @Test void persistsFalseAndUnknownAndAudits(){c.put(101,new StationDisplaySettingsController.Request(false,null,0L));assertEquals(false,db.queryForObject("SELECT power_factor_visible FROM station_display_settings WHERE station_id=101",Boolean.class));assertNull(db.queryForObject("SELECT revenue_visible FROM station_display_settings WHERE station_id=101",Boolean.class));assertEquals(1,db.queryForObject("SELECT count(*) FROM station_audit_event",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM station_display_settings WHERE station_id=102",Integer.class));}
 @Test void rejectsStaleVersionAndUnauthorized(){c.put(101,new StationDisplaySettingsController.Request(true,true,0L));assertEquals(409,assertThrows(BusinessException.class,()->c.put(101,new StationDisplaySettingsController.Request(false,false,0L))).status());doThrow(new BusinessException(403,"denied")).when(access).requireStationPermission(102,"asset.edit");assertEquals(403,assertThrows(BusinessException.class,()->c.put(102,new StationDisplaySettingsController.Request(true,true,0L))).status());}
}
